window.console.error=window.alert;try{const t=JSON.parse(document.getElementById("wb").textContent);t.html&&typeof t.html=="string"&&t.html.split(",").forEach(e=>{const[n,s]=e.split("=");n&&/^[a-zA-Z-]+$/.test(n.trim())&&document.documentElement.setAttribute(n.trim(),(s||"").replace(/['"]/g,""))}),["meta","link","script"].forEach(e=>{if(t[e]&&typeof t[e]=="string"){const n=t[e].indexOf("'"),s=n===-1?t[e]:t[e].slice(0,n),o=n===-1?"":t[e].slice(n+1),r=document.createElement(e);s.trim().split(/\s+/).forEach(l=>{const[i,m]=l.split("=");if(i&&/^[a-zA-Z-]+$/.test(i.trim())){const c=i.trim(),a=(m||"").replace(/['"]/g,"");if(e==="script"&&(c.toLowerCase()==="src"||c.toLowerCase().startsWith("on")))return;r.setAttribute(c,a)}}),o.trim()&&(e==="script"?r.textContent=o:r.setAttribute("content",o)),document.head.appendChild(r)}})}catch(t){console.error("Engine Error: "+t.message)}